nfob\n", "a\nx\nfob\na\n"], ["fob\nfob\n", "a\nx\nx\nx\n"], ["a\nx\n", "x\n"]]]==])
local out = {}
for i, c in ipairs(cases) do
  out[i] = { vim.diff(c[1], c[2], { result_type = 'indices', linematch = 40 }), vim.diff(c[1], c[2], { result_type = 'indices', linematch = 3 }) }
end
io.stdout:write(vim.json.encode(out) .. "\n")
